package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import io.circe.Json
import io.circe.syntax._

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = metadata ++ newMeta)
  }
}

// ============================================================================
// Protocols / Traits
// ============================================================================

trait Tokenizable {
  def toToken: String
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): Seq[String] = {
    _items.map(func)
  }
}

class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.STRING)
  }

  // Overload to handle bytes if needed, mimicking Python's Union[str, bytes]
  def tokenize(value: Array[Byte]): Token = {
    val strValue = new String(value, encoding)
    tokenize(strValue)
  }
}

class NumericTokenizer[T: Numeric](
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[T] {

  def tokenize(value: T): Token = {
    val strValue = value match {
      case d: BigDecimal =>
        d.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString
      case f: Float =>
        f"%.${precision}f".format(f)
      case d: Double =>
        f"%.${precision}f".format(d)
      case _ =>
        value.toString
    }

    Token(
      strValue,
      TokenType.NUMERIC,
      Map("original_type" -> value.getClass.getSimpleName)
    )
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) {

  private val IsoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: LocalDateTime): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(IsoFormat)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }

  def tokenize(value: LocalDate): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DateFormat)
    Token(value.format(fmt), TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizerDouble = new NumericTokenizer[Double]()
  private val numericTokenizerInt = new NumericTokenizer[Int]()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)
    case i: Int => numericTokenizerInt.tokenize(i)
    case d: Double => numericTokenizerDouble.tokenize(d)
    case f: Float => new NumericTokenizer[Float]().tokenize(f)
    case bd: BigDecimal => new NumericTokenizer[BigDecimal]().tokenize(bd)
    case l: Long => new NumericTokenizer[Long]().tokenize(l)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Token Registry
// ============================================================================

class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry = _registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = _handlers :+ handler
  }

  def process(key: String): Seq[Option[Token]] = {
    _registry.get(key) match {
      case None => Seq.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.to(LazyList).flatMap(handler => handler(item)).headOption
        }
    }
  }
}

// ============================================================================
// Token Functor
// ============================================================================

class TokenFunctor[T](private val _value: T) {

  def map[R](func: T => R): TokenFunctor[R] = {
    new TokenFunctor(func(_value))
  }

  def flatMap[R](func: T => TokenFunctor[R]): TokenFunctor[R] = {
    func(_value)
  }

  def get: T = _value

  def getOrElse[B >: T](default: B): B = {
    if (_value != null) _value else default
  }
