    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    // Simple dot notation implementation for compatibility
    // In a real Scala app, we'd use Circe's cursors
    val parts = path.split("\\.")

    parts.foldLeft(Option(value.hcursor)) { (cursor, part) =>
      cursor.flatMap { c =>
        // Try as object field
        val fieldCursor = c.downField(part)
        if (fieldCursor.succeeded) Some(fieldCursor)
        else {
          // Try as array index
          scala.util.Try(part.toInt).toOption.flatMap { idx =>
            val arrayCursor = c.downN(idx)
            if (arrayCursor.succeeded) Some(arrayCursor) else None
          }
