// ============================================================================ 
// Whitespace Tokenizer
// ============================================================================ 

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val Punctuation = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      // Strip leading/trailing punctuation
      processed = processed.dropWhile(c => Punctuation.contains(c))
                           .reverse.dropWhile(c => Punctuation.contains(c)).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    if (maxLength.exists(max => processed.length > max)) {
      processed = processed.substring(0, maxLength.get)
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map {
        processed =>
        Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }
}

// ============================================================================ 
// Tokenizer Builder
// ============================================================================ 

case class TokenizerBuilder[T](
    normalizers: List[String => String] = Nil,
    validators: List[T => Boolean] = Nil,
    metadata: Map[String, Any] = Map.empty
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    copy(normalizers = normalizers :+ normalizer)
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    copy(validators = validators :+ validator)
  }

  def withMetadata(newMeta: (String, Any)*): TokenizerBuilder[T] = {
    copy(metadata = metadata ++ newMeta.toMap)
  }

  def build(): T => Token = {
    // Capture current state
    val finalNormalizers = normalizers
    val finalValidators = validators
    val finalMetadata = metadata

    (value: T) => {
      // Validate
      finalValidators.foreach {
        validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString

      // Normalize
      finalNormalizers.foreach {
        normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, finalMetadata)
    }
  }
}

